package com.gameaggregator.featureflagservice.application;import static org.assertj.core.api.Assertions.assertThat;import java.util.UUID;import org.junit.jupiter.api.Test;class FeatureFlagRolloutTest{@Test void rolloutIsDeterministic(){UUID client=UUID.randomUUID();boolean first=FeatureFlagService.inRollout("new-ui",client,35);assertThat(FeatureFlagService.inRollout("new-ui",client,35)).isEqualTo(first);}@Test void zeroAndFullRolloutHaveExpectedResult(){UUID client=UUID.randomUUID();assertThat(FeatureFlagService.inRollout("flag",client,0)).isFalse();assertThat(FeatureFlagService.inRollout("flag",client,100)).isTrue();}}